import {studentBatch} from './student-profile.mjs';
import {sharesLeaderboardIdentity,publicLeaderboardName} from './leaderboard-privacy.mjs';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percent=value=>Number(value.toFixed(2))+'%';
function randomSeed(crypto){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const hex=[...b].map(v=>v.toString(16).padStart(2,'0')).join('');return [hex.slice(0,8),hex.slice(8,12),hex.slice(12,16),hex.slice(16,20),hex.slice(20)].join('-');}
export function attachBatchLeaderboard(container,{getState,load,makeSeed=()=>randomSeed(container.ownerDocument.defaultView.crypto)}={}){
 let identity='',epoch=0,seed=null,page=0,result=null,busy=false,error='',setup=false,visible=false;
 const owner=()=>{const s=getState();return JSON.stringify([s.user?.id||'guest',studentBatch(s.user),sharesLeaderboardIdentity(s.user),publicLeaderboardName(s.user),s.ready]);};
 function paint(){
  const s=getState(),batch=studentBatch(s.user),ready=s.user&&s.ready&&batch!==null;
  container.innerHTML=`<div class="eyebrow">YOUR BATCH, YOUR JOURNEY</div><h1>Under the <em>same sky.</em></h1><p class="leaderboard-intro">${ready?'ID '+batch+' · Major-course completion':'Sign in and choose your batch to see its leaderboard.'}</p>${ready?`<div class="leaderboard-toolbar"><span>${result?result.total+' students':'Your batch leaderboard'}</span><button class="secondary" data-leaderboard="refresh"${busy?' disabled':''}>${busy?'Loading…':'Refresh'}</button><button class="secondary" data-account="open">Leaderboard privacy</button></div><p class="leaderboard-status" role="status">${esc(error||(!result&&busy?'Loading saved student progress…':''))}</p>${result?`<div class="leaderboard-self">${result.self?'<span>Your position</span><strong>#'+result.self.rank+'</strong><b>'+percent(result.self.percentage)+'</b>':'Save your student journey to appear here.'}</div><div class="leaderboard-table-wrap"><table class="leaderboard-table"><thead><tr><th scope="col">Rank</th><th scope="col">Student</th><th scope="col">Major courses</th><th scope="col">Completed</th></tr></thead><tbody>${result.rows.map(row=>`<tr${row.self?' class="leaderboard-you"':''}><td>#${row.rank}</td><th scope="row">${esc(row.name)}${row.self?'<small>You</small>':''}</th><td>${row.completed} / ${row.required}</td><td><strong>${percent(row.percentage)}</strong><span class="leaderboard-meter" aria-hidden="true"><i style="width:${row.percentage}%"></i></span></td></tr>`).join('')}</tbody></table>${!result.rows.length?'<p>No students on this page yet.</p>':''}</div><div class="leaderboard-pagination"><button class="secondary" data-leaderboard="previous"${page===0||busy?' disabled':''}>Previous</button><span>Page ${page+1} / ${Math.max(1,Math.ceil(result.total/result.pageSize))}</span><button class="secondary" data-leaderboard="next"${(page+1)*result.pageSize>=result.total||busy?' disabled':''}>Next</button></div>`:setup?'<p>Student progress and privacy settings remain available while the leaderboard is being set up.</p>':''}<details class="leaderboard-notes"><summary>Ranking and privacy</summary><p>Rankings use the percentage of required major courses completed on each student’s saved path. Shared courses and the confirmed specialization count; non-major subjects, grades and quiz points do not. Equal percentages share a rank.</p><p>Progress and batch IDs are self-reported. Admin experiments stay outside the leaderboard. Refresh after syncing to see your latest saved progress.</p><p>Names stay anonymous unless the student enables name sharing in Account. Anonymous numbers are shuffled for this view and are independent of rank, signup order and alphabetical order.</p></details>`:`<button class="primary" data-account="open">${s.user?'Choose my batch':'Sign in'}</button>`}`;
 }
 function syncIdentity({reload=true}={}){if(identity!==owner()){identity=owner();epoch++;seed=null;page=0;result=null;busy=false;error='';setup=false;paint();if(reload&&visible&&getState().user&&getState().ready&&studentBatch(getState().user)!==null)refresh();}}
 async function refresh({newAliases=false}={}){
  syncIdentity({reload:false});const s=getState();if(!s.user||!s.ready||studentBatch(s.user)===null){paint();return;}
  const token=++epoch,captured=identity;if(newAliases){seed=null;page=0;}seed??=makeSeed();busy=true;error='';setup=false;result=null;paint();
  try{const next=await load({seed,page});if(token!==epoch||captured!==owner())return;result=next;}
  catch(failure){if(token!==epoch||captured!==owner())return;error=failure.message;setup=failure.setupRequired===true;}
  finally{if(token===epoch&&captured===owner()){busy=false;paint();}}
 }
 container.addEventListener('click',event=>{const action=event.target.closest('[data-leaderboard]')?.dataset.leaderboard;if(!action||busy)return;if(action==='refresh'){refresh({newAliases:true});return;}if(action==='next')page++;if(action==='previous')page=Math.max(0,page-1);refresh();});
 paint();return {syncIdentity,open(){visible=true;syncIdentity({reload:false});refresh({newAliases:true});},close(){visible=false;epoch++;busy=false;result=null;paint();}};
}
